{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C05","C08","C14","C15","C16","C23","C06","C10","C11","C22","C31","C32","C35","C39"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C05","C08","C14","C15","C16","C23","C06","C10","C11","C22"],
  "claims": [
    {
      "claim": "Norfloxacin, the closest N-ethyl pyridone carboxylic acid analog with human data, has measured oral bioavailability of 30-40% (C05, C08, C15, C16), fasting systemic availability estimated at 22-60% with mean 40% (C14), and 35-45% in another report (C23), all above the 20% threshold.",
      "card_ids": ["C05","C08","C14","C15","C16","C23"]
    },
    {
      "claim": "Ofloxacin and levofloxacin, quinolone analogs with the same 4-oxo-3-carboxylic acid core, show absolute oral bioavailability approaching or virtually 100% in healthy volunteers (C10, C22), about 100% systemic availability in fasted subjects (C06), and 80-95% in cystic fibrosis patients (C11).",
      "card_ids": ["C06","C10","C11","C22"]
    },
    {
      "claim": "L3 nalidixic acid oral exposure records in a human crossover show measurable systemic exposure after oral dosing (AUC 17.25-17.34 µg·h/mL; Cmax 4.159-6.346 µg/mL), supporting oral absorption of an N-ethyl quinolone acid without a basic piperazine, although no absolute F is reported.",
      "card_ids": ["C31","C32","C35","C39"]
    },
    {
      "claim": "Norfloxacin's limited ruminant bioavailability (C21) is species-specific and does not contradict the human values above 20%.",
      "card_ids": ["C21"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C31","C32","C35","C39"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability exists for the exact query molecule.",
    "No L3 record reports an F value for nalidixic acid or the query; only oral AUC/Cmax are available.",
    "The query's dianionic bis-carboxylic acid structure and absence of a basic amine are not covered by any direct F record; closest analogs are mono-acid or zwitterionic.",
    "Transporter-mediated absorption, food effects, formulation, and first-pass metabolism for the query are unverified.",
    "Species-dependent quinolone bioavailability (e.g., limited ruminant norfloxacin, C21) may not reflect human absorption."
  ],
  "decision_summary": "Level-3 oral exposure records add nalidixic acid AUC/Cmax evidence showing measurable human oral absorption for a close N-ethyl quinolone acid, but they do not provide an F value and do not overturn the prior high prediction. The closest measured human F values for norfloxacin (30-45%) and ofloxacin/levofloxacin (~100%) remain above 20%, and no affirmative threshold-relevant evidence supports F < 20%. Prediction remains high with moderate confidence."
}

